// pytypes.mjs — Python value model helpers.
//
// Value mapping used across the port:
//   Python int   -> BigInt        (exact, arbitrary precision)
//   Python float -> JS number     (IEEE double, same as CPython)
//   Python str   -> JS string
//   Python bool  -> JS boolean
//   Python None  -> null
//   Python list  -> JS Array
//   Python tuple -> PyTuple
//   Python dict  -> PyDict        (insertion-ordered pair list)
//   Python set   -> PySet

export class PyTuple {
  constructor(items = []) {
    this.items = items;
  }
}

export class PySet {
  constructor(items = []) {
    this.items = items;
  }
}

function toIntLike(v) {
  if (typeof v === 'bigint') return v;
  if (typeof v === 'boolean') return v ? 1n : 0n;
  if (typeof v === 'number' && Number.isInteger(v) && Number.isSafeInteger(v)) {
    return BigInt(v);
  }
  return null;
}

// Python `==` semantics for the key types we support (int/float/bool cross-compare).
export function pyKeyEq(a, b) {
  const ia = toIntLike(a);
  const ib = toIntLike(b);
  if (ia !== null && ib !== null) return ia === ib;
  if (typeof a === 'number' && typeof b === 'number') return a === b;
  if (typeof a === 'bigint' && typeof b === 'number') return Number(a) === b;
  if (typeof a === 'number' && typeof b === 'bigint') return a === Number(b);
  if (typeof a === 'string' && typeof b === 'string') return a === b;
  if (a === null || b === null) return a === b;
  if (a instanceof PyTuple && b instanceof PyTuple) {
    return (
      a.items.length === b.items.length &&
      a.items.every((x, i) => pyKeyEq(x, b.items[i]))
    );
  }
  return a === b;
}

export class PyDict {
  constructor(pairs = []) {
    this.pairs = [];
    for (const [k, v] of pairs) this.set(k, v);
  }

  _index(k) {
    for (let i = 0; i < this.pairs.length; i++) {
      if (pyKeyEq(this.pairs[i][0], k)) return i;
    }
    return -1;
  }

  set(k, v) {
    const i = this._index(k);
    if (i >= 0) this.pairs[i][1] = v;
    else this.pairs.push([k, v]);
  }

  get(k) {
    const i = this._index(k);
    return i >= 0 ? this.pairs[i][1] : undefined;
  }

  has(k) {
    return this._index(k) >= 0;
  }

  keys() {
    return this.pairs.map(([k]) => k);
  }

  values() {
    return this.pairs.map(([, v]) => v);
  }

  items() {
    return this.pairs.map(([k, v]) => new PyTuple([k, v]));
  }
}

// --- float repr (CPython repr algorithm: shortest round-trip digits) ---

export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (!Number.isFinite(x)) return x > 0 ? 'inf' : '-inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';

  const neg = x < 0;
  const s = Math.abs(x).toString(); // shortest round-trip digits, like CPython

  // Normalize to: value = 0.digits * 10^decpt (digits: no leading/trailing zeros)
  let mantissa = s;
  let exp = 0;
  const eIdx = s.indexOf('e');
  if (eIdx >= 0) {
    mantissa = s.slice(0, eIdx);
    exp = parseInt(s.slice(eIdx + 1), 10);
  }
  const dotIdx = mantissa.indexOf('.');
  const intPart = dotIdx >= 0 ? mantissa.slice(0, dotIdx) : mantissa;
  const fracPart = dotIdx >= 0 ? mantissa.slice(dotIdx + 1) : '';
  let digits = intPart + fracPart;
  let decpt = intPart.length + exp;
  let lead = 0;
  while (lead < digits.length && digits[lead] === '0') lead++;
  digits = digits.slice(lead).replace(/0+$/, '');
  decpt -= lead;
  if (digits === '') return neg ? '-0.0' : '0.0';

  let out;
  if (decpt > 16 || decpt <= -4) {
    // exponential notation: d[.ddd]e±XX (exponent at least 2 digits)
    const e = decpt - 1;
    const m = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const eAbs = String(Math.abs(e)).padStart(2, '0');
    out = `${m}e${e < 0 ? '-' : '+'}${eAbs}`;
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return neg ? '-' + out : out;
}

// --- string repr (CPython quote selection and escaping) ---

export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

// --- generic repr / str ---

export function pyRepr(v) {
  if (v === null || v === undefined) return 'None';
  if (v === true) return 'True';
  if (v === false) return 'False';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') return pyFloatRepr(v);
  if (typeof v === 'string') return pyStrRepr(v);
  if (Array.isArray(v)) return '[' + v.map(pyRepr).join(', ') + ']';
  if (v instanceof PyTuple) {
    if (v.items.length === 0) return '()';
    if (v.items.length === 1) return '(' + pyRepr(v.items[0]) + ',)';
    return '(' + v.items.map(pyRepr).join(', ') + ')';
  }
  if (v instanceof PyDict) {
    return (
      '{' +
      v.pairs.map(([k, val]) => pyRepr(k) + ': ' + pyRepr(val)).join(', ') +
      '}'
    );
  }
  if (v instanceof PySet) {
    if (v.items.length === 0) return 'set()';
    return '{' + v.items.map(pyRepr).join(', ') + '}';
  }
  return String(v);
}

// Python str(): identical to repr except top-level strings stay unquoted.
export function pyStr(v) {
  if (typeof v === 'string') return v;
  return pyRepr(v);
}

export function pyTypeName(v) {
  if (v === null || v === undefined) return 'NoneType';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'number') return 'float';
  if (typeof v === 'string') return 'str';
  if (Array.isArray(v)) return 'list';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PySet) return 'set';
  return 'object';
}

// isinstance(x, int) — bool is a subclass of int in Python.
export function isPyInt(v) {
  return typeof v === 'bigint' || typeof v === 'boolean';
}

export function isPyIntOrFloat(v) {
  return isPyInt(v) || typeof v === 'number';
}

// Python-style modulo (result takes the sign of the divisor).
export function pyMod(a, b) {
  if (typeof a === 'bigint' || typeof b === 'bigint') {
    const x = typeof a === 'boolean' ? (a ? 1n : 0n) : BigInt(a);
    const y = typeof b === 'boolean' ? (b ? 1n : 0n) : BigInt(b);
    return ((x % y) + y) % y;
  }
  return ((a % b) + b) % b;
}

// pyliteral.mjs — parser for Python literal syntax (the subset `eval` accepts
// for plain data): dicts, lists, tuples, sets, strings (with escapes, raw and
// triple-quoted forms, adjacent-literal concatenation), ints (dec/hex/oct/bin,
// underscores), floats, True/False/None, unary +/- on numbers.

import { PyDict, PyTuple, PySet } from './pytypes.mjs';

export function pyEval(src) {
  let pos = 0;

  const skipWs = () => {
    while (pos < src.length && /\s/.test(src[pos])) pos++;
  };

  const expect = (ch) => {
    skipWs();
    if (src[pos] !== ch) {
      throw new SyntaxError(`expected '${ch}' at position ${pos}`);
    }
  };

  function parseEscape() {
    const e = src[pos++];
    switch (e) {
      case 'n': return '\n';
      case 't': return '\t';
      case 'r': return '\r';
      case 'a': return '\x07';
      case 'b': return '\b';
      case 'f': return '\f';
      case 'v': return '\v';
      case '\\': return '\\';
      case "'": return "'";
      case '"': return '"';
      case '\n': return ''; // line continuation
      case 'x': {
        const h = src.slice(pos, pos + 2);
        pos += 2;
        return String.fromCodePoint(parseInt(h, 16));
      }
      case 'u': {
        const h = src.slice(pos, pos + 4);
        pos += 4;
        return String.fromCodePoint(parseInt(h, 16));
      }
      case 'U': {
        const h = src.slice(pos, pos + 8);
        pos += 8;
        return String.fromCodePoint(parseInt(h, 16));
      }
      default:
        if (e >= '0' && e <= '7') {
          let oct = e;
          while (oct.length < 3 && src[pos] >= '0' && src[pos] <= '7') {
            oct += src[pos++];
          }
          return String.fromCodePoint(parseInt(oct, 8));
        }
        // unknown escape: Python keeps the backslash
        return '\\' + e;
    }
  }

  function parseString(raw = false) {
    let result = '';
    for (;;) {
      skipWs();
      const q = src[pos];
      const triple = src.startsWith(q.repeat(3), pos);
      pos += triple ? 3 : 1;
      while (pos < src.length) {
        if (triple ? src.startsWith(q.repeat(3), pos) : src[pos] === q) {
          pos += triple ? 3 : 1;
          break;
        }
        const ch = src[pos++];
        result += !raw && ch === '\\' ? parseEscape() : ch;
      }
      // adjacent string literal concatenation: "a" "b" -> "ab"
      skipWs();
      const nxt = src[pos];
      if (nxt !== "'" && nxt !== '"') break;
    }
    return result;
  }

  function parseNumber() {
    if (src.startsWith('0x', pos) || src.startsWith('0X', pos)) {
      pos += 2;
      let h = '';
      while (/[0-9a-fA-F_]/.test(src[pos] || '')) h += src[pos++];
      return BigInt('0x' + h.replace(/_/g, ''));
    }
    if (src.startsWith('0o', pos) || src.startsWith('0O', pos)) {
      pos += 2;
      let o = '';
      while (/[0-7_]/.test(src[pos] || '')) o += src[pos++];
      return BigInt('0o' + o.replace(/_/g, ''));
    }
    if (src.startsWith('0b', pos) || src.startsWith('0B', pos)) {
      pos += 2;
      let b = '';
      while (/[01_]/.test(src[pos] || '')) b += src[pos++];
      return BigInt('0b' + b.replace(/_/g, ''));
    }
    let s = '';
    let isFloat = false;
    while (/[0-9_]/.test(src[pos] || '')) s += src[pos++];
    if (src[pos] === '.') {
      isFloat = true;
      s += src[pos++];
      while (/[0-9_]/.test(src[pos] || '')) s += src[pos++];
    }
    if (src[pos] === 'e' || src[pos] === 'E') {
      isFloat = true;
      s += src[pos++];
      if (src[pos] === '+' || src[pos] === '-') s += src[pos++];
      while (/[0-9_]/.test(src[pos] || '')) s += src[pos++];
    }
    s = s.replace(/_/g, '');
    return isFloat ? Number(s) : BigInt(s);
  }

  function parseBrace() {
    pos++; // consume '{'
    skipWs();
    if (src[pos] === '}') {
      pos++;
      return new PyDict();
    }
    const first = parseValue();
    skipWs();
    if (src[pos] === ':') {
      const d = new PyDict();
      pos++;
      d.set(first, parseValue());
      skipWs();
      while (src[pos] === ',') {
        pos++;
        skipWs();
        if (src[pos] === '}') break;
        const k = parseValue();
        expect(':');
        pos++;
        d.set(k, parseValue());
        skipWs();
      }
      expect('}');
      pos++;
      return d;
    }
    // set literal
    const items = [first];
    while (src[pos] === ',') {
      pos++;
      skipWs();
      if (src[pos] === '}') break;
      items.push(parseValue());
      skipWs();
    }
    expect('}');
    pos++;
    return new PySet(items);
  }

  function parseList() {
    pos++; // consume '['
    const items = [];
    skipWs();
    if (src[pos] === ']') {
      pos++;
      return items;
    }
    for (;;) {
      items.push(parseValue());
      skipWs();
      if (src[pos] !== ',') break;
      pos++;
      skipWs();
      if (src[pos] === ']') break;
    }
    expect(']');
    pos++;
    return items;
  }

  function parseParen() {
    pos++; // consume '('
    skipWs();
    if (src[pos] === ')') {
      pos++;
      return new PyTuple([]);
    }
    const first = parseValue();
    skipWs();
    if (src[pos] !== ',') {
      expect(')');
      pos++;
      return first; // plain parenthesized expression
    }
    const items = [first];
    while (src[pos] === ',') {
      pos++;
      skipWs();
      if (src[pos] === ')') break;
      items.push(parseValue());
      skipWs();
    }
    expect(')');
    pos++;
    return new PyTuple(items);
  }

  function parseValue() {
    skipWs();
    const ch = src[pos];
    if (ch === '{') return parseBrace();
    if (ch === '[') return parseList();
    if (ch === '(') return parseParen();
    if (ch === "'" || ch === '"') return parseString(false);
    if ((ch === 'r' || ch === 'R') && (src[pos + 1] === "'" || src[pos + 1] === '"')) {
      pos++;
      return parseString(true);
    }
    if (ch === '+' || ch === '-') {
      if (/[0-9.]/.test(src[pos + 1] || '')) {
        pos++;
        const n = parseNumber();
        return ch === '-' ? -n : n;
      }
      throw new SyntaxError(`unexpected '${ch}' at position ${pos - 1}`);
    }
    if (/[0-9.]/.test(ch)) return parseNumber();
    if (src.startsWith('True', pos)) { pos += 4; return true; }
    if (src.startsWith('False', pos)) { pos += 5; return false; }
    if (src.startsWith('None', pos)) { pos += 4; return null; }
    throw new SyntaxError(`unexpected character '${ch}' at position ${pos}`);
  }

  const value = parseValue();
  skipWs();
  if (pos < src.length) {
    throw new SyntaxError(`unexpected trailing characters at position ${pos}`);
  }
  return value;
}

// iterutils.mjs — reimplementation of the boltons.iterutils functions used by
// the source program: flatten, chunked, partition, bucketize.

import { PyDict, PyTuple, PySet } from './pytypes.mjs';

// boltons treats strings (and bytes) as atomic; only real containers recurse.
export function isIterable(v) {
  return (
    Array.isArray(v) ||
    v instanceof PyDict ||
    v instanceof PyTuple ||
    v instanceof PySet
  );
}

// Iterating a Python dict yields its keys.
function* pyIter(v) {
  if (v instanceof PyDict) yield* v.keys();
  else if (v instanceof PyTuple) yield* v.items;
  else if (v instanceof PySet) yield* v.items;
  else yield* v;
}

export function* flatten(iterable) {
  for (const item of pyIter(iterable)) {
    if (isIterable(item)) yield* flatten(item);
    else yield item;
  }
}

// boltons chunked yields list chunks; the last one may be shorter.
export function* chunked(src, size) {
  for (let i = 0; i < src.length; i += size) {
    yield src.slice(i, i + size);
  }
}

// Returns a (truthy_items, falsy_items) pair.
export function partition(src, keyFn) {
  const truthy = [];
  const falsy = [];
  for (const item of src) {
    if (keyFn(item)) truthy.push(item);
    else falsy.push(item);
  }
  return new PyTuple([truthy, falsy]);
}

// Groups items into a dict {key: [items]} preserving first-seen key order.
export function bucketize(src, keyFn) {
  const d = new PyDict();
  for (const item of src) {
    const k = keyFn(item);
    if (!d.has(k)) d.set(k, []);
    d.get(k).push(item);
  }
  return d;
}

// dictutils.mjs — reimplementation of the boltons.dictutils classes used by
// the source program: OMD (OrderedMultiDict) and FrozenDict.

import { PyDict, PyTuple, pyKeyEq, pyRepr } from './pytypes.mjs';

export class OMD {
  constructor() {
    this.pairs = []; // all (key, value) pairs, multi-values preserved
  }

  add(k, v) {
    this.pairs.push([k, v]);
  }

  // Unique keys in first-insertion order (like list(omd.keys())).
  keys() {
    const out = [];
    for (const [k] of this.pairs) {
      if (!out.some((seen) => pyKeyEq(seen, k))) out.push(k);
    }
    return out;
  }

  // omd[k] returns the most recently added value for k.
  getLast(k) {
    for (let i = this.pairs.length - 1; i >= 0; i--) {
      if (pyKeyEq(this.pairs[i][0], k)) return this.pairs[i][1];
    }
    return undefined;
  }

  // dict(omd): unique keys, last value wins.
  toDict() {
    const d = new PyDict();
    for (const k of this.keys()) d.set(k, this.getLast(k));
    return d;
  }

  repr() {
    const tuples = this.pairs.map(([k, v]) => new PyTuple([k, v]));
    return 'OrderedMultiDict(' + pyRepr(tuples) + ')';
  }
}

export class FrozenDict {
  constructor(dictLike) {
    this.dict = dictLike; // a PyDict
  }

  items() {
    return this.dict.items();
  }

  repr() {
    return 'FrozenDict(' + pyRepr(this.dict) + ')';
  }
}

// argparse.mjs — minimal emulation of the Python argparse configuration used
// by the source program:
//
//   parser.add_argument('--a', type=str, required=True,
//                       help='Nested dictionary structure')
//
// Mirrors argparse behavior: usage/error text on stderr with exit code 2,
// -h/--help on stdout with exit code 0, supports "--a VALUE" and "--a=VALUE".

import { basename } from 'node:path';

export function parseArgs(argv) {
  const prog = basename(argv[1] || 'test19.mjs');
  const usage = `usage: ${prog} [-h] --a A`;

  const fail = (msg) => {
    process.stderr.write(`${usage}\n${prog}: error: ${msg}\n`);
    process.exit(2);
  };

  const printHelp = () => {
    process.stdout.write(
      `${usage}\n\n` +
        `options:\n` +
        `  -h, --help  show this help message and exit\n` +
        `  --a A       Nested dictionary structure\n`
    );
    process.exit(0);
  };

  const rest = argv.slice(2);
  let aValue;
  let aSeen = false;
  const extras = [];

  for (let i = 0; i < rest.length; i++) {
    const arg = rest[i];
    if (arg === '-h' || arg === '--help') {
      printHelp();
    } else if (arg === '--a') {
      if (i + 1 >= rest.length) fail('argument --a: expected one argument');
      aValue = rest[++i];
      aSeen = true;
    } else if (arg.startsWith('--a=')) {
      aValue = arg.slice(4);
      aSeen = true;
    } else {
      extras.push(arg);
    }
  }

  if (!aSeen) fail('the following arguments are required: --a');
  if (extras.length > 0) fail(`unrecognized arguments: ${extras.join(' ')}`);

  return { a: aValue };
}

